// Serverless function to serve Harjit-Singh-CV.pdf on Vercel
const PDF_B64 = "";
const pdfBuffer = Buffer.from(PDF_B64, "base64");

module.exports = (req, res) => {
  const isView = req.url && req.url.includes("view=1");
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader(
    "Content-Disposition",
    (isView ? "inline" : "attachment") + '; filename="Harjit-Singh-CV.pdf"'
  );
  res.setHeader("Content-Length", pdfBuffer.length);
  res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
  if (typeof res.status === "function") {
    res.status(200);
  } else {
    res.statusCode = 200;
  }
  res.end(pdfBuffer);
};
